# identify block vs markers per color via component analysis
def comps(i,color):
    H,W=len(i),len(i[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if i[r][c]==color and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and i[ny][nx]==color and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append(cells)
    return out

def detect(i):
    H,W=len(i),len(i[0]); cnt=Counter(x for r in i for x in r); bg=cnt.most_common(1)[0][0]
    orders=sorted((k,len(comps(i,k))) for k in cnt if k!=bg)
    info={}
    for k in cnt:
        if k==bg: continue
        cs=comps(i,k); nmax=max(len(c) for c in cs)
        info[k]=(cs,nmax)
    # block: color with exactly one large-ish component (size > others?) pick by max comp size descending; markers = rest
    block=max(info.items(), key=lambda kv:(kv[1][1], len(kv[1][0])))
    mks=min((k for k in info if k!=block[0]), key=lambda k:info[k][1][1]) if len([k for k in info if k!=block[0]]) else None
    if mks is None: mks=max((k for k in info if k!=block[0]), key=lambda k:-cnt[k])
    mset={(r,c) for r in range(H) for c in range(W) if i[r][c]==mks}
    B={(r,c) for r in range(H) for c in range(W) if i[r][c]==block[0]}
    return bg,B,mset,info[block[0]][0]

