# Demo 5 is the tie-break: markers (6,13)..(12,19) diagonal down-right; output = anti-diagonal r+c=19 from (7,12) to (12,7).
# Marker start (topmost-first) is (6,13); ray goes down-left starting at neighbor (7,12) until grid edge (row 12 = last).
# So rule: extension is perpendicular to marker line, starts one step past marker tip along the perpendicular direction, 
# travels in that perpendicular direction (both signs? demo3 shows both directions), exits at grid boundary.
def f(i):
    H,W=len(i),len(i[0]); o=[r[:] for r in i]
    cnt=Counter(x for r in i for x in r); bg=cnt.most_common(1)[0][0]
    info={}
    for k in cnt:
        if k==bg: continue
        cs=comps(i,k); nmax=max(len(c) for c in cs)
        info[k]=(cs,nmax)
    blk=max(info,key=lambda k:info[k][1]); mks=min((k for k in info if k!=blk),key=lambda k:-cnt[k])
    B={(r,c) for r in range(H) for c in range(W) if i[r][c]==blk}
    M={(r,c) for r in range(H) for c in range(W) if i[r][c]==mks}
    # marker line orientation: slope from first-to-last
    p0,minp=min(M); p1=max(M)
    vr,pv=p1[0]-minp[0], p1[1]-minp[1]
    if abs(vr)==abs(pv): d=(sign(vr),sign(pv)) if pv else (1,0)
    else: d=(1,sign(pv)) if abs(pv)>1 and abs(vr)==1 else (sign(vr),0) if abs(vr)>1 else (1,1)
    def sign(x): return 1 if x>0 else (-1 if x<0 else 0)
    dr,dc=d
    # perpendicular directions
    perps=[(-dc,dr),(dc,-dr)]
    res=set()
    for pr,pc in perps:
        rr,cc=[minp], [minp[1]]
        q=[(rr[0]+pr, cc[0]+pc)]
        while True:
            nr,nc=q.pop()
            if not(0<=nr<H and 0<=nc<W): break
            if (nr,nc) in B or (nr,nc) in M:
                pass
            elif o[nr][nc]!=3:
                res.add((nr,nc)); q.append((nr+pr,nc+pc))
        if res:
            break
    for (r,c) in res: o[r][c]=3
    return o

